actions.script:
try {
  def upload=ec.web.parameters.bundleFile
  def catalog=ec.web.parameters.bundleJson
  if (upload && upload.metaClass.respondsTo(upload,'getInputStream')) {
      if (upload.getSize()>10000000) {ec.message.addError('Catalog file must be at most 10 MB.');return}
      catalog=upload.getInputStream().withCloseable { new String(it.readAllBytes(),'UTF-8') }
  }
  ec.service.sync().name('zenith.saas.CleanWorkspaceServices.create#Workspace').parameters([bundleJson:catalog,apply:false]).call()
} finally {
  // Do not echo a private catalog in qapps currentParameters or refill it after redirect.
  ['bundleJson','bundleFile'].each { key -> ec.web.parameters.put(key,null); ec.web.requestParameters.put(key,null); ec.context.put(key,null) }
}

try {
  def upload=ec.web.parameters.bundleFile
  def catalog=ec.web.parameters.bundleJson
  if (upload && upload.metaClass.respondsTo(upload,'getInputStream')) {
      if (upload.getSize()>10000000) {ec.message.addError('Catalog file must be at most 10 MB.');return}
      catalog=upload.getInputStream().withCloseable { new String(it.readAllBytes(),'UTF-8') }
  }
  ec.service.sync().name('zenith.saas.CleanWorkspaceServices.create#Workspace').parameters([bundleJson:catalog,apply:true,confirmationDigest:confirmationDigest,adminPassword:adminPassword,cashierOnePassword:cashierOnePassword,cashierTwoPassword:cashierTwoPassword]).call()
} finally {
  // Framework redirect JSON otherwise includes submitted currentParameters.
  ['bundleJson','bundleFile','adminPassword','cashierOnePassword','cashierTwoPassword','confirmationDigest'].each { key ->
      ec.web.parameters.put(key,null); ec.web.requestParameters.put(key,null); ec.context.put(key,null)
  }
}
